// SfxCatalog — the sound effect vocabulary, as data.
//
// Mirrors the shape of buddy_parts_catalog.dart / asset_paths.dart: this file
// holds no logic, just the mapping from a semantic id the game code names
// (`Sfx.correct`) to a file on disk. Call sites should never spell out an
// asset path — that's what keeps a future audio re-cut a one-file change.
//
// Clips are generated by tools/audio/generate_placeholder_sfx.py. They're
// placeholders: warm and readable, but plain. Replace the files in place when
// real audio arrives; nothing in Dart needs to change.
//
// Format is .wav rather than the .m4a that specs/shared/asset-paths.md
// mandates for narration. AAC decoding in just_audio_web is browser-dependent
// (Firefox especially), these clips are small, and WAV decodes everywhere.
// Recorded in that spec's changelog as an SFX-only exception.

/// Level the music bed sits at out of the box.
///
/// Well under the sound effects because the bed plays *underneath* narration
/// and must never compete with the voice telling a child what to do. Retuned
/// down from 0.35 when the generated pad was replaced by a real recording,
/// which is mastered and carries far more of its energy in the midrange the
/// narrator occupies.
const double kDefaultMusicVolume = 0.33;

/// Level the sound effects sit at out of the box.
const double kDefaultSfxVolume = 0.9;

/// Every sound the game can make, named by what it *means* rather than what it
/// sounds like — so re-cutting the audio never forces a rename here.
enum Sfx {
  /// Navigation / chrome.
  uiTap,
  whoosh,
  bubbleIn,

  /// Answer feedback.
  correct,
  wrongSoft,
  hint,

  /// Rewards.
  coin,
  fanfare,
  eggCrack,

  /// Buddy's non-verbal reactions. The Buddy never speaks in scenes
  /// (specs/shared/k-activity-patterns.md), so these are wordless chirps.
  buddyHappy,
  buddyCurious,

  /// Gameplay sprites.
  pop,
  drop,
  sparkle,

  /// 100ms of nothing, used to unlock the web audio context inside a user
  /// gesture without the child hearing a blip. See SfxEngine.unlock().
  silence,
}

class SfxClip {
  const SfxClip({
    required this.asset,
    this.poolSize = 2,
    this.gain = 1.0,
  });

  final String asset;

  /// How many players stay warm for this clip. Greater than 1 lets rapid
  /// repeats overlap instead of cutting each other off — which matters for
  /// anything a child can trigger twice in under a second.
  final int poolSize;

  /// Per-clip level trim, applied on top of the user's SFX volume. Lets a
  /// clip sit right in the mix without re-rendering the file.
  final double gain;
}

const Map<Sfx, SfxClip> kSfxCatalog = <Sfx, SfxClip>{
  Sfx.uiTap: SfxClip(asset: 'assets/audio/sfx/ui/tap.wav', gain: 0.55),
  Sfx.whoosh: SfxClip(asset: 'assets/audio/sfx/ui/whoosh.wav', gain: 0.45),
  Sfx.bubbleIn: SfxClip(asset: 'assets/audio/sfx/ui/bubble-in.wav', gain: 0.6),
  Sfx.correct:
      SfxClip(asset: 'assets/audio/sfx/feedback/correct-chime.wav', gain: 0.8),
  // Deliberately quiet. A wrong answer needs to be *noticed*, not punished —
  // specs/shared/art-direction.md calls for a soft puff, never a buzzer.
  Sfx.wrongSoft:
      SfxClip(asset: 'assets/audio/sfx/feedback/wrong-soft.wav', gain: 0.5),
  Sfx.hint: SfxClip(asset: 'assets/audio/sfx/feedback/hint.wav', gain: 0.6),
  Sfx.coin: SfxClip(
    asset: 'assets/audio/sfx/reward/coin.wav',
    poolSize: 4,
    gain: 0.7,
  ),
  Sfx.fanfare: SfxClip(
    asset: 'assets/audio/sfx/reward/fanfare.wav',
    poolSize: 1,
    gain: 0.85,
  ),
  Sfx.eggCrack: SfxClip(
    asset: 'assets/audio/sfx/reward/egg-crack.wav',
    poolSize: 1,
    gain: 0.8,
  ),
  Sfx.buddyHappy:
      SfxClip(asset: 'assets/audio/sfx/buddy/happy.wav', gain: 0.65),
  Sfx.buddyCurious:
      SfxClip(asset: 'assets/audio/sfx/buddy/curious.wav', gain: 0.6),
  Sfx.pop:
      SfxClip(asset: 'assets/audio/sfx/sprite/pop.wav', poolSize: 3, gain: 0.5),
  Sfx.drop: SfxClip(asset: 'assets/audio/sfx/sprite/drop.wav', gain: 0.6),
  Sfx.sparkle:
      SfxClip(asset: 'assets/audio/sfx/sprite/sparkle.wav', gain: 0.45),
  Sfx.silence:
      SfxClip(asset: 'assets/audio/sfx/silence.wav', poolSize: 1, gain: 0.0),
};

/// The counting ladder: one note per counted object, climbing a C-major scale.
///
/// This is the game's one genuinely *pedagogical* sound. Tapping the third
/// fawn plays the third note, so the child hears quantity ascend — the audio
/// channel carries the number line rather than just decorating it. Counting to
/// three is three rising notes; counting to ten climbs past the octave and
/// resolves.
///
/// Major scale, not chromatic semitones: a chromatic run past ~5 notes reads as
/// atonal and anxious to a five-year-old, and reward signals are meant to be
/// warm (specs/shared/art-direction.md).
///
/// Pre-rendered rather than pitch-shifted at runtime on purpose —
/// `AudioPlayer.setPitch()` is Android-only, and `setSpeed()` on web maps to
/// `playbackRate` with `preservesPitch = true`, which changes tempo, not pitch.
const List<String> kCountLadder = <String>[
  'assets/audio/sfx/counting/count-01.wav',
  'assets/audio/sfx/counting/count-02.wav',
  'assets/audio/sfx/counting/count-03.wav',
  'assets/audio/sfx/counting/count-04.wav',
  'assets/audio/sfx/counting/count-05.wav',
  'assets/audio/sfx/counting/count-06.wav',
  'assets/audio/sfx/counting/count-07.wav',
  'assets/audio/sfx/counting/count-08.wav',
  'assets/audio/sfx/counting/count-09.wav',
  'assets/audio/sfx/counting/count-10.wav',
  'assets/audio/sfx/counting/count-11.wav',
  'assets/audio/sfx/counting/count-12.wav',
];

/// The Mystic Sanctuary theme.
///
/// A real recording rather than the generated pentatonic pad that stood in for
/// it, and four minutes long — a whole sub-mode usually plays through without
/// ever reaching the loop point, which is the cheapest possible answer to a
/// seam in the audio.
///
/// MP3 rather than the WAV the SFX use: at four minutes, 16-bit PCM would be
/// 42 MB. It ships at 320 kbps stereo exactly as delivered, minus a 366 KB ID3
/// tag that was carrying cover art into a web build.
const String kSanctuaryMusicBed = 'assets/audio/music/forest-mystical.mp3';

/// Music beds, keyed by the `scene.musicBed` strings already authored in
/// data/lesson-runtime/*.json. Unmapped keys fall back to [kDefaultMusicBed]
/// rather than going silent, so adding a bed name to a lesson never breaks it.
///
/// `sanctuary-low` and `sanctuary-picnic` deliberately resolve to the *same*
/// file, and SfxEngine treats the resolved asset — not the key — as the bed's
/// identity. So a lesson asking for the picnic bed partway through a visit
/// does not restart the music: the two names describe one place, and the
/// Sanctuary is meant to sound like one continuous piece from the moment the
/// kid walks in until the moment they leave.
///
/// The challenge bed stays a separate file on purpose. Opting into a challenge
/// mode is one of the few places a change in the music is the point.
const Map<String, String> kMusicBeds = <String, String>{
  'sanctuary-low': kSanctuaryMusicBed,
  'sanctuary-picnic': kSanctuaryMusicBed,
  'sanctuary-challenge-rising-energy':
      'assets/audio/music/sanctuary-challenge-rising.wav',
};

const String kDefaultMusicBed = 'sanctuary-low';

/// The higher-energy bed for opt-in challenge modes. Named here rather than
/// spelled out at the call site so the key stays checkable against
/// [kMusicBeds].
const String kChallengeMusicBed = 'sanctuary-challenge-rising-energy';
